 await py.runPythonAsync("\"\"\"Recover missing version proposals only from four complete printed circle outlines.\"\"\"\nimport cv2\nimport numpy as np\n\ndef version_outlines(gray, header):\n    left, top, width, _ = header\n    x0, x1 = left, left + width\n    y0, y1 = top - 125, top\n    if x0 < 0 or y0 < 0 or x1 > gray.shape[1] or y1 > gray.shape[0]:\n        return None\n    mask = np.uint8(gray[y0:y1, x0:x1] < 150) * 255\n    contours, _ = cv2.findContours(mask, cv2.RETR_EXTERNAL, cv2.CHAIN_APPROX_NONE)\n    result = []\n    for contour in contours:\n        x, y, w, h = cv2.boundingRect(contour)\n        if x <= 0 or y <= 0 or x+w >= mask.shape[1] or y+h >= mask.shape[0] or not (29 < w < 45 and 29 < h < 45) or len(contour) < 5:\n            continue\n        (cx, cy), (ew, eh), _ = cv2.fitEllipse(contour)\n        if not (.85 < ew/eh < 1.18 and 16 < (ew+eh)/4 < 22 and top-100 < y0+cy < top-25):\n            continue\n        # The external contour must contain a nearly complete circumference.\n        radii = np.sqrt(((contour[:, 0, :] - [cx, cy])**2).sum(axis=1))\n        if np.mean(np.abs(radii - (ew+eh)/4) < 2.5) < .9:\n            continue\n        result.append([float(x0+cx), float(y0+cy), float((ew+eh)/4)])\n    result.sort(key=lambda p: p[0])\n    if len(result) != 4 or np.ptp([p[1] for p in result]) > 8 or any(not 65 < result[i+1][0]-result[i][0] < 95 for i in range(3)):\n        return None\n    return np.float32(result)\n\nclass VersionProposalRecovery:\n    def __init__(self, headers, hough):\n        self.original_headers = headers\n        self.original_hough = hough\n        self.clear()\n\n    def clear(self):\n        self.gray = None\n        self.bars = None\n\n    def headers(self, gray):\n        bars = self.original_headers(gray)\n        self.gray, self.bars = gray, bars\n        return bars\n\n    def hough(self, gray, *args, **kwargs):\n        proposed = self.original_hough(gray, *args, **kwargs)\n        if gray is not self.gray or proposed is None or kwargs.get('param2') != 23:\n            return proposed\n        left, top, width, _ = self.bars[-1]\n        inside = (proposed[0,:,0] > left) & (proposed[0,:,0] < left+width) & (proposed[0,:,1] > top-100) & (proposed[0,:,1] < top-25)\n        existing = proposed[0][inside]\n        if len(existing) >= 4:\n            return proposed\n        outlines = version_outlines(gray, self.bars[-1])\n        if outlines is None or any(min(np.linalg.norm(p[:2]-q[:2]) for q in outlines) > 6.5 for p in existing):\n            return proposed\n        return np.concatenate([proposed[0][~inside], outlines])[None, :, :]\r\n\nimport physical_layout\n_base_headers=physical_layout.headers\n_base_hough=cv2.HoughCircles\n_version_recovery=VersionProposalRecovery(_base_headers,_base_hough)");
 await py.runPythonAsync("\"\"\"Skip exact duplicate marker masks; no changed geometry or ink thresholds.\"\"\"\nimport cv2\nimport numpy as np\n\ndef distinct_marker_proposals(gray):\n    h, w = gray.shape\n    proposals = []\n    # Preserve mask/contour order; identical clamped block sizes add no proposals.\n    blocks = dict.fromkeys(max(31, min(151, round(f*w) | 1)) for f in (.07, .10, .13))\n    for block in blocks:\n        for offset in (7, 11, 15):\n            binary = cv2.adaptiveThreshold(gray, 255, cv2.ADAPTIVE_THRESH_GAUSSIAN_C, cv2.THRESH_BINARY_INV, block, offset)\n            # A dark tabletop can form a closed contour around the entire page.\n            # Markers inside that contour still require individual inspection.\n            contours, _ = cv2.findContours(binary, cv2.RETR_LIST, cv2.CHAIN_APPROX_SIMPLE)\n            for contour in contours:\n                x, y, bw, bh = cv2.boundingRect(contour)\n                if not (.6 < bw/bh < 1.6 and .012*w < bw < .065*w and np.mean(binary[y:y+bh, x:x+bw] > 0) > .85):\n                    continue\n                if not ((x < .25*w or x > .75*w) and (y < .35*h or y > .55*h)):\n                    continue\n                if x <= 0 or y <= 0 or x+bw >= w-1 or y+bh >= h-1:\n                    continue\n                center = [x+bw/2, y+bh/2]\n                if all(np.linalg.norm(np.array(center)-p['center']) > .009*w for p in proposals):\n                    proposals.append({'center': center, 'box': [x, y, bw, bh]})\n    return proposals\n\n\nphysical_layout.marker_proposals=distinct_marker_proposals");
 await py.runPythonAsync("\"\"\"Exact binary rectangular morphology for the two existing header kernels.\"\"\"\nimport cv2\nimport numpy as np\n\ndef binary_rectangle(src, shape, erode):\n    height, width = shape\n    ay, ax = height//2, width//2\n    binary = np.uint8(src != 0)\n    padded = np.pad(binary, ((ay, height-ay-1), (ax, width-ax-1)),\n                    mode='constant', constant_values=1 if erode else 0)\n    sums = cv2.integral(padded, sdepth=cv2.CV_32S)\n    count = sums[height:, width:] - sums[:-height, width:] - sums[height:, :-width] + sums[:-height, :-width]\n    return np.uint8(count == height*width if erode else count > 0)*255\n\nclass BinaryHeaderMorphology:\n    def __init__(self, original):\n        self.original = original\n\n    def __call__(self, src, operation, kernel, *args, **kwargs):\n        if (args or kwargs or src.dtype != np.uint8 or src.ndim != 2\n                or kernel.shape not in ((3, 17), (9, 230))\n                or operation not in (cv2.MORPH_OPEN, cv2.MORPH_CLOSE)\n                or not np.all(kernel == 1) or np.any((src != 0) & (src != 255))):\n            return self.original(src, operation, kernel, *args, **kwargs)\n        first_erodes = operation == cv2.MORPH_OPEN\n        return binary_rectangle(binary_rectangle(src, kernel.shape, first_erodes), kernel.shape, not first_erodes)\n\n_base_morphology=cv2.morphologyEx\n_header_morphology=BinaryHeaderMorphology(_base_morphology)");
