self.onmessage=async event=>{
 if(event.data?.type==='qr'){
  try{const result=await AZMDeviceQR.readDeviceQr(new Blob([event.data.image],{type:event.data.mime||'image/jpeg'}),event.data.quick===true);self.postMessage({state:'qr-complete',result})}
  catch{self.postMessage({state:'qr-error',message:'QR reading could not finish on this device.'})}
  return;
 }
 if(event.data?.type==='prepare'){
  try{await initialize();self.postMessage({state:'prepared'})}catch{runtime=null;self.postMessage({state:'prepare-error'})}
  return;
 }
 if(event.data?.type!=='scan')return;
 let stage='loading';const started=performance.now();let readingStarted=started;
 try{
  const py=await initialize();readingStarted=performance.now();stage='reading';self.postMessage({state:'reading'});
  py.FS.writeFile('/scan-in-memory',new Uint8Array(event.data.image));
  let result;
  try{result=await py.runPythonAsync(`cv2.adaptiveThreshold=_fast_masks\ncv2.morphologyEx=_header_morphology\nphysical_layout.headers=_version_recovery.headers\ncv2.HoughCircles=_version_recovery.hough\n_bytes=open('/scan-in-memory','rb').read()\n_frame=cv2.imdecode(np.frombuffer(_bytes,np.uint8),cv2.IMREAD_COLOR)\nif _frame is None: raise ValueError('Unreadable image')\ntry:\n _result,_=recognize(_frame,_profile)\nexcept InvalidScan as _failure:\n _safe={'physical_missing_or_ambiguous_markers','physical_four_headers_required','physical_row_ruler_mismatch','physical_page_cropped','physical_marker_geometry_mismatch','physical_circle_evidence_incomplete','physical_version_region_unverified'}\n _reasons=[_a.get('reason') for _a in (_failure.diagnostics or {}).get('attempts',[]) if _a.get('reason') in _safe]\n _priority=['physical_version_region_unverified','physical_row_ruler_mismatch','physical_circle_evidence_incomplete','physical_four_headers_required','physical_page_cropped','physical_marker_geometry_mismatch','physical_missing_or_ambiguous_markers']\n _best=next((_reason for _reason in _priority if _reason in _reasons),'unknown')\n raise ValueError('geometry diagnostic: '+_best) from None\nif _result.get('physicalValidationRequired'):\n _scale=1.15 if _frame.shape[0]*_frame.shape[1]*1.15*1.15<=20000000 else 0.90\n _second,_=recognize(cv2.resize(_frame,None,fx=_scale,fy=_scale,interpolation=cv2.INTER_LINEAR),_profile)\n if _result['paperVersion']['answer'] != _second['paperVersion']['answer']: raise ValueError('Version geometry is inconsistent')\n for _first,_other in zip(_result['responses'],_second['responses']):\n  if _first['answer'] != _other['answer'] or _other['reviewRequired']:\n   _first.update(answer='UNCERTAIN',reviewRequired=True)\njson.dumps({'responses':[{'question':r['question'],'answer':r['answer'],'reviewRequired':r['reviewRequired']} for r in _result['responses']], 'paperVersion':_result['paperVersion']['answer'], 'identity':_result.get('identity'), 'qrEnvelope':_result.get('qrEnvelope'), 'qrDiagnostics':_result.get('qrDiagnostics'), 'officialScoringAllowed':False})`)}
  finally{py.FS.unlink('/scan-in-memory');await py.runPythonAsync("cv2.adaptiveThreshold=_base_adaptive\ncv2.morphologyEx=_base_morphology\nphysical_layout.headers=_base_headers\ncv2.HoughCircles=_base_hough\n_version_recovery.clear()\n_fast_masks.clear()\nglobals().pop('_bytes',None);globals().pop('_frame',None);globals().pop('_result',None);globals().pop('_second',None);globals().pop('_',None);globals().pop('_first',None);globals().pop('_other',None)")}
  self.postMessage({state:'complete',result:{...JSON.parse(result),processingMs:Math.round(performance.now()-readingStarted),initializationMs:Math.round(readingStarted-started)}});
 }catch(error){const text=String(error);let message=stage==='loading'?'The on-device scanner could not load. Check your connection and reopen the app.':/Version geometry is inconsistent/.test(text)?'The two on-device version checks disagree. Retake or check the marked paper version.':/physical_missing_or_ambiguous_markers|physical_marker_geometry_mismatch|physical_page_cropped/.test(text)?'Printed corner markers could not be verified. Move closer while keeping the entire page and all four black squares visible.':/physical_four_headers_required|physical_row_ruler_mismatch|physical_circle_evidence_incomplete/.test(text)?'The answer grid could not be verified. Keep all four column headings and bubbles sharp, with even light.':/registration_failed|timing_track_mismatch|template_registration_failed|physical_|geometry diagnostic/.test(text)?'The page markers or answer grid could not be verified. Retake with the whole sheet sharp and visible.':/image_too_blurry/.test(text)?'The sheet is too blurry. Hold steady and retake in brighter light.':'The device could not finish reading this image. Retake the sheet or reopen the app.';const known=[['physical_missing_or_ambiguous_markers','M'],['physical_marker_geometry_mismatch','G'],['physical_page_cropped','P'],['physical_four_headers_required','H'],['physical_row_ruler_mismatch','R'],['physical_circle_evidence_incomplete','C'],['physical_version_region_unverified','V'],['Version geometry is inconsistent','D']];const flags=known.filter(([value])=>text.includes(value)).map(([,label])=>label);if(flags.length)message+=' (Diagnostic '+flags.join('')+').';self.postMessage({state:'error',message});}
};
